262		/**
263		 * Create a sibling application (one with the same parent). A side effect of calling
264		 * this method is that the current application (and its parent) are started without
265		 * any arguments if they are not already running. To supply arguments when starting
266		 * the current application and its parent use {@link #sibling(Class[], String...)}
267		 * instead.
268		 * @param sources the sources for the application (Spring configuration)
269		 * @return the new sibling builder
270		 */
271		public SpringApplicationBuilder sibling(Class<?>... sources) {
272			return runAndExtractParent().child(sources);
273		}
274	
275		/**
276		 * Create a sibling application (one with the same parent). A side effect of calling
277		 * this method is that the current application (and its parent) are started if they
278		 * are not already running.
279		 * @param sources the sources for the application (Spring configuration)
280		 * @param args the command line arguments to use when starting the current app and its
281		 * parent
282		 * @return the new sibling builder
283		 */
284		public SpringApplicationBuilder sibling(Class<?>[] sources, String... args) {
285			return runAndExtractParent(args).child(sources);
286		}
