426		/**
427		 * Default properties for the environment in the form {@code key=value} or
428		 * {@code key:value}. Multiple calls to this method are cumulative and will not clear
429		 * any previously set properties.
430		 * @param defaultProperties the properties to set.
431		 * @return the current builder
432		 * @see SpringApplicationBuilder#properties(Properties)
433		 * @see SpringApplicationBuilder#properties(Map)
434		 */
435		public SpringApplicationBuilder properties(String... defaultProperties) {
436			return properties(getMapFromKeyValuePairs(defaultProperties));
437		}
438	
439		private Map<String, Object> getMapFromKeyValuePairs(String[] properties) {
440			Map<String, Object> map = new HashMap<>();
441			for (String property : properties) {
442				int index = lowestIndexOf(property, ":", "=");
443				String key = (index > 0) ? property.substring(0, index) : property;
444				String value = (index > 0) ? property.substring(index + 1) : "";
445				map.put(key, value);
446			}
447			return map;
448		}
449	
450		private int lowestIndexOf(String property, String... candidates) {
451			int index = -1;
452			for (String candidate : candidates) {
453				int candidateIndex = property.indexOf(candidate);
454				if (candidateIndex > 0) {
455					index = (index != -1) ? Math.min(index, candidateIndex) : candidateIndex;
456				}
457			}
458			return index;
459		}
460	
461		/**
462		 * Default properties for the environment.Multiple calls to this method are cumulative
463		 * and will not clear any previously set properties.
464		 * @param defaultProperties the properties to set.
465		 * @return the current builder
466		 * @see SpringApplicationBuilder#properties(String...)
467		 * @see SpringApplicationBuilder#properties(Map)
468		 */
469		public SpringApplicationBuilder properties(Properties defaultProperties) {
470			return properties(getMapFromProperties(defaultProperties));
471		}
472	
473		private Map<String, Object> getMapFromProperties(Properties properties) {
474			Map<String, Object> map = new HashMap<>();
475			for (Object key : Collections.list(properties.propertyNames())) {
476				map.put((String) key, properties.get(key));
477			}
478			return map;
479		}
480	
481		/**
482		 * Default properties for the environment. Multiple calls to this method are
483		 * cumulative and will not clear any previously set properties.
484		 * @param defaults the default properties
485		 * @return the current builder
486		 * @see SpringApplicationBuilder#properties(String...)
487		 * @see SpringApplicationBuilder#properties(Properties)
488		 */
489		public SpringApplicationBuilder properties(Map<String, Object> defaults) {
490			this.defaultProperties.putAll(defaults);
491			this.application.setDefaultProperties(this.defaultProperties);
492			if (this.parent != null) {
493				this.parent.properties(this.defaultProperties);
494				this.parent.environment(this.environment);
495			}
496			return this;
497		}
