171		 * Return {@code true} if objects of {@code sourceType} can be converted to the
172		 * {@code targetType} and the converter has {@code Object.class} as a supported source
173		 * type.
174		 * @param sourceType the source type to test
175		 * @param targetType the target type to test
176		 * @return if conversion happens through an {@code ObjectTo...} converter
177		 * @since 2.4.3
178		 */
179		public boolean isConvertViaObjectSourceType(TypeDescriptor sourceType, TypeDescriptor targetType) {
180			GenericConverter converter = getConverter(sourceType, targetType);
181			Set<ConvertiblePair> pairs = (converter != null) ? converter.getConvertibleTypes() : null;
182			if (pairs != null) {
183				for (ConvertiblePair pair : pairs) {
184					if (Object.class.equals(pair.getSourceType())) {
185						return true;
186					}
187				}
188			}
189			return false;
