302		 * bean factory.
303		 * @param registry the service to register beans with
304		 * @param beanFactory the bean factory to get the beans from
305		 * @param qualifier the qualifier required on the beans or {@code null}
306		 * @return the beans that were added
307		 * @since 3.5.0
308		 */
309		public static Map<String, Object> addBeans(FormatterRegistry registry, ListableBeanFactory beanFactory,
310				@Nullable String qualifier) {
311			ConfigurableListableBeanFactory configurableBeanFactory = getConfigurableListableBeanFactory(beanFactory);
312			Map<String, Object> beans = getBeans(beanFactory, qualifier);
313			beans.forEach((beanName, bean) -> {
314				BeanDefinition beanDefinition = (configurableBeanFactory != null)
315						? configurableBeanFactory.getMergedBeanDefinition(beanName) : null;
316				ResolvableType type = (beanDefinition != null) ? beanDefinition.getResolvableType() : null;
317				addBean(registry, bean, type);
318			});
319			return beans;
320		}
