322		private static @Nullable ConfigurableListableBeanFactory getConfigurableListableBeanFactory(
323				ListableBeanFactory beanFactory) {
324			if (beanFactory instanceof ConfigurableApplicationContext applicationContext) {
325				return applicationContext.getBeanFactory();
326			}
327			if (beanFactory instanceof ConfigurableListableBeanFactory configurableListableBeanFactory) {
328				return configurableListableBeanFactory;
329			}
330			return null;
331		}
