333		private static Map<String, Object> getBeans(ListableBeanFactory beanFactory, @Nullable String qualifier) {
334			Map<String, Object> beans = new LinkedHashMap<>();
335			beans.putAll(getBeans(beanFactory, Printer.class, qualifier));
336			beans.putAll(getBeans(beanFactory, Parser.class, qualifier));
337			beans.putAll(getBeans(beanFactory, Formatter.class, qualifier));
338			beans.putAll(getBeans(beanFactory, Converter.class, qualifier));
339			beans.putAll(getBeans(beanFactory, ConverterFactory.class, qualifier));
340			beans.putAll(getBeans(beanFactory, GenericConverter.class, qualifier));
341			return beans;
342		}
