344		private static <T> Map<String, T> getBeans(ListableBeanFactory beanFactory, Class<T> type,
345				@Nullable String qualifier) {
346			return (!StringUtils.hasLength(qualifier)) ? beanFactory.getBeansOfType(type)
347					: BeanFactoryAnnotationUtils.qualifiedBeansOfType(beanFactory, type, qualifier);
348		}
