382		private static <B, T> void addBeanWithType(FormatterRegistry registry, B bean, ResolvableType beanType,
383				Class<T> type, Consumer<B> standardRegistrar,
384				BiFunction<B, ResolvableType, BeanAdapter<?>> beanAdapterFactory) {
385			addBean(registry, bean, beanType, type, standardRegistrar,
386					() -> registry.addConverter(beanAdapterFactory.apply(bean, beanType)));
387		}
388	
389		private static <B, T> void addBean(FormatterRegistry registry, B bean, @Nullable ResolvableType beanType,
390				Class<T> type, Consumer<B> standardRegistrar, @Nullable Runnable beanAdapterRegistrar) {
391			if (beanType != null && beanAdapterRegistrar != null
392					&& ResolvableType.forInstance(bean).as(type).hasUnresolvableGenerics()) {
393				beanAdapterRegistrar.run();
394				return;
395			}
396			standardRegistrar.accept(bean);
397		}
