399		/**
400		 * Base class for adapters that adapt a bean to a {@link GenericConverter}.
401		 *
402		 * @param <B> the base type of the bean
403		 */
404		abstract static class BeanAdapter<B> implements ConditionalGenericConverter {
405	
406			private final B bean;
407	
408			private final ResolvableTypePair types;
409	
410			BeanAdapter(B bean, ResolvableType beanType) {
411				Assert.isInstanceOf(beanType.toClass(), bean);
412				ResolvableType type = ResolvableType.forClass(getClass()).as(BeanAdapter.class).getGeneric();
413				ResolvableType[] generics = beanType.as(type.toClass()).getGenerics();
414				this.bean = bean;
415				this.types = getResolvableTypePair(generics);
416			}
417	
418			protected ResolvableTypePair getResolvableTypePair(ResolvableType[] generics) {
419				return new ResolvableTypePair(generics[0], generics[1]);
420			}
421	
422			protected B bean() {
423				return this.bean;
424			}
425	
426			@Override
427			public Set<ConvertiblePair> getConvertibleTypes() {
428				return Set.of(new ConvertiblePair(this.types.source().toClass(), this.types.target().toClass()));
429			}
430	
431			@Override
432			public boolean matches(TypeDescriptor sourceType, TypeDescriptor targetType) {
433				return (this.types.target().toClass() == targetType.getObjectType()
434						&& matchesTargetType(targetType.getResolvableType()));
435			}
436	
437			private boolean matchesTargetType(ResolvableType targetType) {
438				ResolvableType ours = this.types.target();
439				return targetType.getType() instanceof Class || targetType.isAssignableFrom(ours)
440						|| this.types.target().hasUnresolvableGenerics();
441			}
442	
443			protected final boolean conditionalConverterCandidateMatches(Object conditionalConverterCandidate,
444					TypeDescriptor sourceType, TypeDescriptor targetType) {
445				return (conditionalConverterCandidate instanceof ConditionalConverter conditionalConverter)
446						? conditionalConverter.matches(sourceType, targetType) : true;
447			}
448	
449			@SuppressWarnings({ "unchecked", "rawtypes" })
450			protected final @Nullable Object convert(@Nullable Object source, TypeDescriptor targetType,
451					Converter<?, ?> converter) {
452				return (source != null) ? ((Converter) converter).convert(source) : convertNull(targetType);
453			}
454	
455			private @Nullable Object convertNull(TypeDescriptor targetType) {
456				return (targetType.getObjectType() != Optional.class) ? null : Optional.empty();
457			}
458	
459			@Override
460			public String toString() {
461				return this.types + " : " + this.bean;
462			}
463	
464		}
