548		/**
549		 * Adapts a {@link ConverterFactory} bean to a {@link GenericConverter}.
550		 */
551		private static final class ConverterFactoryBeanAdapter extends BeanAdapter<ConverterFactory<?, ?>> {
552	
553			ConverterFactoryBeanAdapter(ConverterFactory<?, ?> bean, ResolvableType beanType) {
554				super(bean, beanType);
555			}
556	
557			@Override
558			public boolean matches(TypeDescriptor sourceType, TypeDescriptor targetType) {
559				return super.matches(sourceType, targetType)
560						&& conditionalConverterCandidateMatches(bean(), sourceType, targetType)
561						&& conditionalConverterCandidateMatches(getConverter(targetType::getType), sourceType, targetType);
562			}
563	
564			@Override
565			public @Nullable Object convert(@Nullable Object source, TypeDescriptor sourceType, TypeDescriptor targetType) {
566				return convert(source, targetType, getConverter(targetType::getObjectType));
567			}
568	
569			@SuppressWarnings({ "unchecked", "rawtypes" })
570			private Converter<Object, ?> getConverter(Supplier<Class<?>> typeSupplier) {
571				return ((ConverterFactory) bean()).getConverter(typeSupplier.get());
572			}
