39	/**
40	 * {@link ServletWebServerApplicationContext} that accepts annotated classes as input - in
41	 * particular {@link org.springframework.context.annotation.Configuration @Configuration}
42	 * -annotated classes, but also plain {@link Component @Component} classes and JSR-330
43	 * compliant classes using {@code javax.inject} annotations. Allows for registering
44	 * classes one by one (specifying class names as config location) as well as for classpath
45	 * scanning (specifying base packages as config location).
46	 * <p>
47	 * Note: In case of multiple {@code @Configuration} classes, later {@code @Bean}
48	 * definitions will override ones defined in earlier loaded files. This can be leveraged
49	 * to deliberately override certain bean definitions through an extra Configuration class.
50	 *
51	 * @author Phillip Webb
52	 * @since 4.0.0
53	 * @see #register(Class...)
54	 * @see #scan(String...)
55	 * @see ServletWebServerApplicationContext
56	 */
57	public class AnnotationConfigServletWebServerApplicationContext extends ServletWebServerApplicationContext
58			implements AnnotationConfigRegistry {
59	
60		private final AnnotatedBeanDefinitionReader reader;
61	
62		private final ClassPathBeanDefinitionScanner scanner;
63	
64		private final Set<Class<?>> annotatedClasses = new LinkedHashSet<>();
65	
66		private String @Nullable [] basePackages;
67	
68		/**
69		 * Create a new {@link AnnotationConfigServletWebServerApplicationContext} that needs
70		 * to be populated through {@link #register} calls and then manually
71		 * {@linkplain #refresh refreshed}.
72		 */
73		public AnnotationConfigServletWebServerApplicationContext() {
74			this.reader = new AnnotatedBeanDefinitionReader(this);
75			this.scanner = new ClassPathBeanDefinitionScanner(this);
76		}
77	
78		/**
79		 * Create a new {@link AnnotationConfigServletWebServerApplicationContext} with the
80		 * given {@code DefaultListableBeanFactory}. The context needs to be populated through
81		 * {@link #register} calls and then manually {@linkplain #refresh refreshed}.
82		 * @param beanFactory the DefaultListableBeanFactory instance to use for this context
83		 */
84		public AnnotationConfigServletWebServerApplicationContext(DefaultListableBeanFactory beanFactory) {
85			super(beanFactory);
86			this.reader = new AnnotatedBeanDefinitionReader(this);
87			this.scanner = new ClassPathBeanDefinitionScanner(this);
88		}
89	
90		/**
91		 * Create a new {@link AnnotationConfigServletWebServerApplicationContext}, deriving
92		 * bean definitions from the given annotated classes and automatically refreshing the
93		 * context.
94		 * @param annotatedClasses one or more annotated classes, e.g. {@code @Configuration}
95		 * classes
96		 */
97		public AnnotationConfigServletWebServerApplicationContext(Class<?>... annotatedClasses) {
98			this();
99			register(annotatedClasses);
100			refresh();
101		}
102	
103		/**
104		 * Create a new {@link AnnotationConfigServletWebServerApplicationContext}, scanning
105		 * for bean definitions in the given packages and automatically refreshing the
106		 * context.
107		 * @param basePackages the packages to check for annotated classes
108		 */
109		public AnnotationConfigServletWebServerApplicationContext(String... basePackages) {
110			this();
111			scan(basePackages);
112			refresh();
113		}
114	
115		/**
116		 * {@inheritDoc}
117		 * <p>
118		 * Delegates given environment to underlying {@link AnnotatedBeanDefinitionReader} and
119		 * {@link ClassPathBeanDefinitionScanner} members.
120		 */
121		@Override
122		public void setEnvironment(ConfigurableEnvironment environment) {
123			super.setEnvironment(environment);
124			this.reader.setEnvironment(environment);
125			this.scanner.setEnvironment(environment);
126		}
127	
128		/**
129		 * Provide a custom {@link BeanNameGenerator} for use with
130		 * {@link AnnotatedBeanDefinitionReader} and/or
131		 * {@link ClassPathBeanDefinitionScanner}, if any.
132		 * <p>
133		 * Default is
134		 * {@link org.springframework.context.annotation.AnnotationBeanNameGenerator}.
135		 * <p>
136		 * Any call to this method must occur prior to calls to {@link #register(Class...)}
137		 * and/or {@link #scan(String...)}.
138		 * @param beanNameGenerator the bean name generator
139		 * @see AnnotatedBeanDefinitionReader#setBeanNameGenerator
140		 * @see ClassPathBeanDefinitionScanner#setBeanNameGenerator
141		 */
142		public void setBeanNameGenerator(BeanNameGenerator beanNameGenerator) {
143			this.reader.setBeanNameGenerator(beanNameGenerator);
144			this.scanner.setBeanNameGenerator(beanNameGenerator);
145			getBeanFactory().registerSingleton(AnnotationConfigUtils.CONFIGURATION_BEAN_NAME_GENERATOR, beanNameGenerator);
146		}
147	
148		/**
149		 * Set the {@link ScopeMetadataResolver} to use for detected bean classes.
150		 * <p>
151		 * The default is an {@link AnnotationScopeMetadataResolver}.
152		 * <p>
153		 * Any call to this method must occur prior to calls to {@link #register(Class...)}
154		 * and/or {@link #scan(String...)}.
155		 * @param scopeMetadataResolver the scope metadata resolver
156		 */
157		public void setScopeMetadataResolver(ScopeMetadataResolver scopeMetadataResolver) {
158			this.reader.setScopeMetadataResolver(scopeMetadataResolver);
159			this.scanner.setScopeMetadataResolver(scopeMetadataResolver);
160		}
161	
162		/**
163		 * Register one or more annotated classes to be processed. Note that
164		 * {@link #refresh()} must be called in order for the context to fully process the new
165		 * class.
166		 * <p>
167		 * Calls to {@code #register} are idempotent; adding the same annotated class more
168		 * than once has no additional effect.
169		 * @param annotatedClasses one or more annotated classes, e.g. {@code @Configuration}
170		 * classes
171		 * @see #scan(String...)
172		 * @see #refresh()
173		 */
174		@Override
175		public final void register(Class<?>... annotatedClasses) {
176			Assert.notEmpty(annotatedClasses, "'annotatedClasses' must not be empty");
177			this.annotatedClasses.addAll(Arrays.asList(annotatedClasses));
178		}
179	
180		/**
181		 * Perform a scan within the specified base packages. Note that {@link #refresh()}
182		 * must be called in order for the context to fully process the new class.
183		 * @param basePackages the packages to check for annotated classes
184		 * @see #register(Class...)
185		 * @see #refresh()
186		 */
187		@Override
188		public final void scan(String... basePackages) {
189			Assert.notEmpty(basePackages, "'basePackages' must not be empty");
190			this.basePackages = basePackages;
191		}
