30	import org.springframework.context.annotation.ImportBeanDefinitionRegistrar;
31	import org.springframework.core.annotation.AnnotationAttributes;
32	import org.springframework.core.annotation.MergedAnnotations;
33	import org.springframework.core.annotation.MergedAnnotations.SearchStrategy;
34	import org.springframework.core.env.Environment;
35	import org.springframework.core.io.ResourceLoader;
36	import org.springframework.core.type.AnnotationMetadata;
37	import org.springframework.core.type.filter.AnnotationTypeFilter;
38	import org.springframework.stereotype.Component;
39	import org.springframework.util.Assert;
40	import org.springframework.util.ClassUtils;
41	import org.springframework.util.StringUtils;
42	
43	/**
44	 * {@link ImportBeanDefinitionRegistrar} for registering
45	 * {@link ConfigurationProperties @ConfigurationProperties} bean definitions through
46	 * scanning.
47	 *
48	 * @author Madhura Bhave
49	 * @author Phillip Webb
50	 */
51	class ConfigurationPropertiesScanRegistrar implements ImportBeanDefinitionRegistrar {
52	
53		private final Environment environment;
54	
55		private final @Nullable ResourceLoader resourceLoader;
56	
57		ConfigurationPropertiesScanRegistrar(Environment environment, @Nullable ResourceLoader resourceLoader) {
58			this.environment = environment;
59			this.resourceLoader = resourceLoader;
60		}
61	
62		@Override
63		public void registerBeanDefinitions(AnnotationMetadata importingClassMetadata, BeanDefinitionRegistry registry) {
64			Set<String> packagesToScan = getPackagesToScan(importingClassMetadata);
65			scan(registry, packagesToScan);
66		}
67	
68		private Set<String> getPackagesToScan(AnnotationMetadata metadata) {
69			AnnotationAttributes attributes = AnnotationAttributes
70				.fromMap(metadata.getAnnotationAttributes(ConfigurationPropertiesScan.class.getName()));
71			Assert.state(attributes != null, "'attributes' must not be null");
72			String[] basePackages = attributes.getStringArray("basePackages");
73			Class<?>[] basePackageClasses = attributes.getClassArray("basePackageClasses");
74			Set<String> packagesToScan = new LinkedHashSet<>(Arrays.asList(basePackages));
75			for (Class<?> basePackageClass : basePackageClasses) {
76				packagesToScan.add(ClassUtils.getPackageName(basePackageClass));
77			}
78			if (packagesToScan.isEmpty()) {
79				packagesToScan.add(ClassUtils.getPackageName(metadata.getClassName()));
80			}
81			packagesToScan.removeIf((candidate) -> !StringUtils.hasText(candidate));
82			return packagesToScan;
83		}
84	
85		private void scan(BeanDefinitionRegistry registry, Set<String> packages) {
86			ConfigurationPropertiesBeanRegistrar registrar = new ConfigurationPropertiesBeanRegistrar(registry);
87			ClassPathScanningCandidateComponentProvider scanner = getScanner(registry);
88			for (String basePackage : packages) {
89				for (BeanDefinition candidate : scanner.findCandidateComponents(basePackage)) {
90					String beanClassName = candidate.getBeanClassName();
91					Assert.state(beanClassName != null, "'beanClassName' must not be null");
92					register(registrar, beanClassName);
93				}
94			}
95		}
96	
97		private ClassPathScanningCandidateComponentProvider getScanner(BeanDefinitionRegistry registry) {
98			ClassPathScanningCandidateComponentProvider scanner = new ClassPathScanningCandidateComponentProvider(false);
99			scanner.setEnvironment(this.environment);
100			scanner.setResourceLoader(this.resourceLoader);
101			scanner.addIncludeFilter(new AnnotationTypeFilter(ConfigurationProperties.class));
102			TypeExcludeFilter typeExcludeFilter = new TypeExcludeFilter();
103			typeExcludeFilter.setBeanFactory((BeanFactory) registry);
104			scanner.addExcludeFilter(typeExcludeFilter);
105			return scanner;
106		}
107	
108		private void register(ConfigurationPropertiesBeanRegistrar registrar, String className) throws LinkageError {
109			try {
110				register(registrar, ClassUtils.forName(className, null));
111			}
112			catch (ClassNotFoundException ex) {
113				// Ignore
114			}
115		}
116	
117		private void register(ConfigurationPropertiesBeanRegistrar registrar, Class<?> type) {
118			if (!isComponent(type)) {
119				registrar.register(type);
120			}
121		}
122	
123		private boolean isComponent(Class<?> type) {
124			return MergedAnnotations.from(type, SearchStrategy.TYPE_HIERARCHY).isPresent(Component.class);
125		}
126	
127	}
